/**
 * GCC SKU / Inventory Classification Benchmarks — Sub-Sector Edition
 *
 * Data model: benchmarks[kpiKey][subSector | '*'][skuClass]
 * The '*' key is the industry-wide fallback used when no sub-sector is
 * selected or when a sub-sector has no specific entry for that KPI.
 *
 * Every manufacturing sub-sector, and every sub-sector in all other
 * industries, has its own calibrated GCC median and top-quartile targets.
 * Values are differentiated by operating model, supply-chain maturity, and
 * inventory dynamics — not just by SKU class.
 *
 * Data vintage: 2024-2025.
 * Sources: APICS/ASCM SCOR v12 · Gartner Supply Chain Analytics 2024 ·
 * Hackett Group World-Class Procurement 2024 · CIPS Inventory Benchmarks 2024
 * · ISC GCC practitioner data 2022-2025.
 */

// ─── Types ────────────────────────────────────────────────────────────────────

export type SkuClassKey =
  | 'finished-goods'
  | 'raw-materials'
  | 'work-in-progress'
  | 'spare-parts-mro'
  | 'indirect-general'
  | 'packaging'
  | 'commodities';

export interface SkuClassMeta {
  id: SkuClassKey;
  label: string;
  labelAr: string;
  icon: string;
  description: string;
}

export const SKU_CLASSES: SkuClassMeta[] = [
  { id: 'finished-goods',   label: 'Finished Goods / Traded',      labelAr: 'بضائع جاهزة / مُتداوَلة',         icon: '📦', description: 'Completed products, retail-ready goods, traded items' },
  { id: 'raw-materials',    label: 'Raw Materials / Direct',        labelAr: 'مواد خام / مباشرة',               icon: '🧱', description: 'Production inputs, direct materials, feedstock' },
  { id: 'work-in-progress', label: 'Work-in-Progress (WIP)',        labelAr: 'تحت التصنيع (WIP)',               icon: '⚙️', description: 'Semi-finished goods, partially processed items' },
  { id: 'spare-parts-mro',  label: 'Spare Parts / MRO',            labelAr: 'قطع غيار / صيانة',               icon: '🔧', description: 'Maintenance, repair, operations parts & capital spares' },
  { id: 'indirect-general', label: 'Indirect / General Items',      labelAr: 'مستلزمات عامة / غير مباشرة',     icon: '📋', description: 'Office supplies, consumables, low-value indirect spend' },
  { id: 'packaging',        label: 'Packaging Materials',           labelAr: 'مواد تغليف',                     icon: '🗳️', description: 'Boxes, labels, pallets, shrink wrap, primary/secondary packaging' },
  { id: 'commodities',      label: 'Bulk Commodities',             labelAr: 'سلع جملة / خام',                 icon: '⛟', description: 'Bulk liquids, chemicals, grains, metals, aggregate' },
];

export interface SkuBenchmarkEntry {
  value: number;
  label: string;
  labelAr: string;
}

type KpiSkuBenchmarks    = Partial<Record<SkuClassKey, SkuBenchmarkEntry>>;
// sub-sector name OR '*' for the industry-wide fallback
type SubSectorBenchmarks = Record<string, KpiSkuBenchmarks>;

// ─── Entry helpers ────────────────────────────────────────────────────────────

const AR: Record<string, string> = {
  '0':'٠','1':'١','2':'٢','3':'٣','4':'٤','5':'٥','6':'٦','7':'٧','8':'٨','9':'٩','.':'٫',
};
function ar(n: number | string): string {
  return String(n).split('').map(c => AR[c] ?? c).join('');
}
const yr  = (v: number): SkuBenchmarkEntry => ({ value: v, label: `${v}×/yr`,  labelAr: `${ar(v)}/سنة`    });
const pct = (v: number): SkuBenchmarkEntry => ({ value: v, label: `${v}%`,     labelAr: `${ar(v)}٪`       });
const d   = (v: number): SkuBenchmarkEntry => ({ value: v, label: `${v} days`, labelAr: `${ar(v)} يوماً`  });

