// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Returns the GCC median benchmark for a KPI + sub-sector + SKU class,
 * falling back to the '*' (industry-wide) entry if no sub-sector match.
 */
export function getSkuClassBenchmark(
  kpiId: string,
  skuClass: SkuClassKey | null,
  subSector?: string | null,
): SkuBenchmarkEntry | null {
  if (!skuClass) return null;
  const table = SKU_CLASS_KPI_BENCHMARKS[kpiId];
  if (!table) return null;
  return (subSector ? table[subSector]?.[skuClass] : undefined)
    ?? table['*']?.[skuClass]
    ?? null;
}

/**
 * Returns the GCC top-quartile target for a KPI + sub-sector + SKU class,
 * falling back to the '*' (industry-wide) entry if no sub-sector match.
 */
export function getSkuClassTopQuartile(
  kpiId: string,
  skuClass: SkuClassKey | null,
  subSector?: string | null,
): SkuBenchmarkEntry | null {
  if (!skuClass) return null;
  const table = SKU_CLASS_KPI_TOP_QUARTILE[kpiId];
  if (!table) return null;
  return (subSector ? table[subSector]?.[skuClass] : undefined)
    ?? table['*']?.[skuClass]
    ?? null;
}

